class R:
    def __init__(self, name):
        self.name = name

class T:
    def __init__(self):
        self.members = [R("樱"), R("凛")]
    def first(self):
        return self.members[0]

print(T().first().name)

class T:
    def __init__(self):
        self.members = []
    def avg(self):
        total = sum(m for m in self.members)
        return total / len(self.members)

print(T().avg())
